import java.lang.reflect.*;import com.tencent.shadow.core.runtime.*;import com.tencent.shadow.core.runtime.container.*;import com.tencent.shadow.core.loader.delegates.*;public class LifecycleHarness {public static void main(String[]a)throws Exception{ShadowActivityDelegate d=new ShadowActivityDelegate();if(d.getPluginActivity()!=null)throw new AssertionError();d.onCreate();PluginContainerActivity container=new PluginContainerActivity(d);ShadowApplication owner=new ShadowApplication();int[] count={0};ShadowActivityLifecycleCallbacks listener=(ShadowActivityLifecycleCallbacks)Proxy.newProxyInstance(LifecycleHarness.class.getClassLoader(),new Class[]{ShadowActivityLifecycleCallbacks.class},(o,m,x)->{count[0]++;return null;});ShadowActivityLifecycleCallbacks.Wrapper w=new ShadowActivityLifecycleCallbacks.Wrapper(listener,owner);java.util.List<Method> callbacks=new java.util.ArrayList<>();for(Method m:w.getClass().getDeclaredMethods()){if(!m.getName().startsWith("onActivity"))continue;callbacks.add(m);Object[] params=m.getParameterCount()==2?new Object[]{container,new android.os.Bundle()}:new Object[]{container};m.invoke(w,params);}if(count[0]!=0)throw new AssertionError("null activity delivered");ShadowActivity activity=new ShadowActivity();activity.setOwner(owner);d.set(activity);if(d.getPluginActivity()!=activity)throw new AssertionError();for(Method m:callbacks){Object[] params=m.getParameterCount()==2?new Object[]{container,new android.os.Bundle()}:new Object[]{container};m.invoke(w,params);}if(count[0]!=callbacks.size()-1)throw new AssertionError("live callbacks lost: "+count[0]+"/"+callbacks.size());container.getClass().getMethod("ultraDetachFailedActivity").invoke(container);if(!container.detached())throw new AssertionError("both fields not cleared");int before=count[0];for(Method m:callbacks){Object[] params=m.getParameterCount()==2?new Object[]{container,new android.os.Bundle()}:new Object[]{container};m.invoke(w,params);}if(count[0]!=before)throw new AssertionError();System.out.println("PASS actual wrapper: "+callbacks.size()+" lifecycle phases tolerate absent/dead delegate, live owned activity callbacks preserved; nullable accessor and both-field detach pass");}}